<div class="text-container"><span class="t s0" style="left:72px;bottom:907px;letter-spacing:-0.11px;word-spacing:6.79px;">Following our comprehensive evaluation of your technical competencies and professional </span>
<span class="t s0" style="left:72px;bottom:884px;letter-spacing:-0.11px;word-spacing:8.52px;">background, we are pleased to formally select you for the position of </span>
<span class="t s0" style="left:72px;bottom:861px;letter-spacing:-0.1px;"><b>{{ $letter->candidate_address }}</b> at The Tech System.</span>
<span class="t s0" style="left:72px;bottom:815px;letter-spacing:-0.09px;word-spacing:0.32px;">Your expertise has been identified as a high-value asset for our upcoming global project pipeline. </span>
<span class="t s0" style="left:72px;bottom:792px;letter-spacing:-0.09px;">By accepting this offer, you are officially integrated into our professional talent roster. </span>
<span class="t s1" style="left:72px;bottom:746px;letter-spacing:-0.11px;">1. Engagement Model &amp; Compensation </span>
<span class="t s0" style="left:72px;bottom:723px;letter-spacing:-0.1px;word-spacing:0.77px;">You are being onboarded into our Project-Ready Bench (PRB) Tier. Under this structured model, </span>
<span class="t s0" style="left:72px;bottom:701px;letter-spacing:-0.1px;word-spacing:1.97px;">your formal employment status begins immediately for the purposes of orientation and client- </span>
<span class="t s0" style="left:72px;bottom:678px;letter-spacing:-0.1px;word-spacing:3.55px;">alignment. Your competitive compensation, amount per hour, will commence and be billable </span>
<span class="t s0" style="left:72px;bottom:655px;letter-spacing:-0.1px;">upon your successful deployment to a client assignment. </span>
<span class="t s1" style="left:72px;bottom:609px;letter-spacing:-0.1px;">2. The Onboarding &amp; Placement Guarantee </span>
<span class="t s0" style="left:72px;bottom:586px;letter-spacing:-0.1px;word-spacing:2.32px;">To ensure a seamless transition into our Fortune 500 client environments, you will undergo a </span>
<span class="t s0" style="left:72px;bottom:563px;letter-spacing:-0.09px;">specialized Readiness Phase, including: </span>
<span class="t s0" style="left:100px;bottom:517px;letter-spacing:-0.09px;">Technical alignment and client-specific environment briefing. </span>
<span class="t s0" style="left:100px;bottom:494px;letter-spacing:-0.1px;">Strategic resume enhancement and interview simulation. </span>
<span class="t s0" style="left:100px;bottom:471px;letter-spacing:-0.09px;">Priority submission to our active project high-value roles. </span>
<span class="t s1" style="left:72px;bottom:425px;letter-spacing:-0.1px;">3. Terms of Acceptance </span>
<span class="t s0" style="left:72px;bottom:402px;letter-spacing:-0.1px;word-spacing:2.2px;">This offer is contingent upon the successful completion of our onboarding formalities and the </span>
<span class="t s0" style="left:72px;bottom:380px;letter-spacing:-0.09px;">validation of your credentials. </span>
<span class="t s0" style="left:72px;bottom:334px;letter-spacing:-0.09px;word-spacing:1.63px;">We are confident that your integration into </span><span class="t s1" style="left:426px;bottom:334px;letter-spacing:-0.11px;word-spacing:1.63px;">The Tech  System</span><span class="t s0" style="left:581px;bottom:334px;letter-spacing:-0.09px;word-spacing:1.63px;">will be the catalyst for the next </span>
<span class="t s0" style="left:72px;bottom:311px;letter-spacing:-0.1px;word-spacing:4.06px;">stage of your career. Please signify your acceptance by signing and returning this letter by </span>
<span class="t s1" style="left:72px;bottom:288px;letter-spacing:-0.1px;"><b>{{ \Carbon\Carbon::parse($letter->due_date)->format('m/d/Y') }}</b></span><span class="t s0" style="left:122px;bottom:288px;">. </span>
<span class="t s0" style="left:72px;bottom:242px;letter-spacing:-0.1px;">Welcome to the team. We look forward to achieving great milestones together. </span>
<span class="t s2" style="left:679px;bottom:958px;letter-spacing:0.17px;">Date: <b>{{ \Carbon\Carbon::parse($letter->letter_date)->format('m/d/Y') }}</b></span>
<span class="t s2" style="left:72px;bottom:182px;letter-spacing:0.19px;">Warm regards, </span>
<span class="t s2" style="left:76px;bottom:154px;letter-spacing:0.17px;">The Tech System Inc. </span>
<span class="t s2" style="left:72px;bottom:936px;letter-spacing:0.17px;">Dear <b>{{ $letter->candidate_name }}</b>, </span>
<span class="t s3" style="left:337px;bottom:1021px;letter-spacing:0.27px;">SELECTION LETTER </span>
<span class="t s4" style="left:566px;bottom:1149px;letter-spacing:0.13px;">+1 (689) 321-1555 </span>
<span class="t s4" style="left:566px;bottom:1128px;letter-spacing:0.16px;">www.thetechsystem.com </span>
<span class="t s4" style="left:566px;bottom:1108px;letter-spacing:0.13px;">10 W, Pine St., Orlando, Florida 32801 </span></div>

</div>

</div>

<script>
    const metadata = JSON.parse(document.getElementById("metadata").text);
    document.title = metadata.title || metadata.fileName;

    const annotations = JSON.parse(document.getElementById("annotations").text);
    const pages = document.querySelectorAll(".page");

    const createAnnotation = function(container, data, pageNo) {
        if (data.type !== "Link" && data.type !== "TextLink") {
            return;
        }
        if (!data.action) {
            return;
        }

        const annotation = document.createElement("div");
        annotation.setAttribute("style", "");
        annotation.style.left = data.bounds[0] + "px";
        annotation.style.top = data.bounds[1] + "px";
        annotation.style.width = data.bounds[2] + "px";
        annotation.style.height = data.bounds[3] + "px";
        annotation.dataset.type = data.type;
        if (data.objref) {
            annotation.dataset.objref = data.objref;
        }

        if (data.appearance) {
            annotation.style.backgroundImage = "url('" + data.appearance + "')";
            annotation.style.backgroundSize = "100% 100%";
        }

        if (data.action.type === "URI") {
            const element = document.createElement("a");
            element.href = data.action.uri;
            element.title = data.action.uri;
            element.target = "_blank";
            element.style.position = "absolute";
            element.style.width = "100%";
            element.style.height = "100%";
            annotation.appendChild(element);
        } else {
            annotation.addEventListener("click", () => {
                switch (data.action.type) {
                    case "GoTo":
                        pages[data.action.page - 1].scrollIntoView();
                        break;

                    case "Named":
                        switch (data.action.name) {
                            case "NextPage":
                                pages[pageNo - 2].scrollIntoView();
                                break;
                            case "PrevPage":
                                pages[pageNo].scrollIntoView();
                                break;
                            case "FirstPage":
                                pages[0].scrollIntoView();
                                break;
                            case "LastPage":
                                pages[metadata.pagecount - 1].scrollIntoView();
                                break;
                        }
                        break;
                }
            });
        }
        container.append(annotation);
    };

    annotations.pages.forEach(pageAnnotations => {
        const pageNo = pageAnnotations.page;
        const annotationsContainer = document.createElement("div");
        annotationsContainer.className = "annotations-container";
        annotationsContainer.style.width = metadata.bounds[pageNo - 1][0];
        annotationsContainer.style.height = metadata.bounds[pageNo - 1][1];
        pageAnnotations.annotations.forEach(annotation => createAnnotation(annotationsContainer, annotation, pageNo));
        pages[pageNo - 1].appendChild(annotationsContainer);
    });
</script>

<script>
document.getElementById("printBtn").addEventListener("click", function() {
    const pageContainer = document.querySelector(".page-container");

    // Hide all other elements on the page (including the print button)
    const bodyChildren = Array.from(document.body.children);
    bodyChildren.forEach(el => {
        if (el !== pageContainer) {
            el.style.display = 'none';
        }
    });

    // Print only the page-container
    window.print();

    // Restore original display
    bodyChildren.forEach(el => {
        if (el !== pageContainer) {
            el.style.display = '';
        }
    });
});
</script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/dom-to-image-more@2.9.0/dist/dom-to-image-more.min.js"></script>
<script>
document.getElementById("downloadBtn").addEventListener("click", async function () {
    const element = document.getElementById("pagecontainer");

    // ✅ Clone element for isolated rendering
    const clonedElement = element.cloneNode(true);

    // ✅ Minimal print isolation (NOT style matching)
    const printStyle = document.createElement("style");
    printStyle.textContent = `
        @page {
            size: A4 portrait;
            margin: 0;
        }

        body {
            margin: 0 !important;
            background: #fff !important;
        }

        .page-container {
            width: 210mm;
            height: 297mm;
            margin: 0;
            padding: 0;
        }
    `;
    clonedElement.prepend(printStyle);

    // ✅ Allow layout & assets to settle
    await new Promise(resolve => setTimeout(resolve, 5));

    // ✅ A4 pixel dimensions
    const a4WidthPx = 1175;
    const a4HeightPx = Math.round(a4WidthPx * 1.4142);

    // ✅ html2pdf options (logic-aligned)
    const opt = {
        margin: [0, 0, 0, 0],
        filename: 'page.pdf',
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: {
            scale: 3,
            useCORS: true,
            scrollY: 0,
            backgroundColor: "#ffffff",
            logging: false,
            letterRendering: true
        },
        jsPDF: {
            unit: 'px',
            format: [a4WidthPx, a4HeightPx],
            orientation: 'portrait'
        },
        pagebreak: {
            mode: ['avoid-all', 'css', 'legacy']
        }
    };

    // ✅ Convert Iconify icons → images (FIXED)
    clonedElement.querySelectorAll("iconify-icon").forEach(icon => {
        const img = document.createElement("img");
        const iconName = icon.getAttribute("icon");

        img.src = `https://api.iconify.design/${iconName}.svg?color=%23000`;
        img.width = 34;
        img.height = 34;
        img.style.filter = "contrast(250%) brightness(0%)";

        icon.replaceWith(img);
    });

    // ✅ Generate PDF
    await html2pdf().set(opt).from(clonedElement).save();
});
</script>

</body>
</html>